input.command:
psql -v ON_ERROR_STOP=1 <<'EOF'
-- Tiny copies WITHOUT the FK so an unjoinable product is representable.
CREATE TEMP TABLE u_orders   (order_id bigint, order_date timestamptz, status text);
CREATE TEMP TABLE u_items    (order_item_id bigint, order_id bigint, product_id bigint, quantity int, unit_price numeric);
CREATE TEMP TABLE u_products (product_id bigint, category text);
INSERT INTO u_orders VALUES (1, '2025-01-05', 'COMPLETED'),
                            (2, '2025-01-06', 'COMPLETED'),
                            (3, '2025-01-07', 'PENDING');
-- order 1: controlling line (id 1) references product 999 which does not exist
INSERT INTO u_items VALUES (1, 1, 999, 4, 10.00),
                           (2, 1, 7,   5, 20.00),
                           (3, 3, 7,   6, 30.00);
INSERT INTO u_products VALUES (7, 'HARDWARE');

WITH completed_orders AS (
    SELECT o.order_id, to_char(o.order_date, 'YYYY-MM') AS month
    FROM u_orders o WHERE o.status = 'COMPLETED'
),
controlling_line AS (
    SELECT DISTINCT ON (oi.order_id) oi.order_id, oi.quantity, oi.unit_price, p.category
    FROM u_items oi LEFT JOIN u_products p ON p.product_id = oi.product_id
    ORDER BY oi.order_id, oi.order_item_id
),
attributed AS (
    SELECT co.order_id, co.month,
           COALESCE(cl.category, '(no items)') AS category,
           COALESCE(cl.quantity * cl.unit_price, 0) AS line_revenue,
           COALESCE(cl.quantity, 0) AS line_units
    FROM completed_orders co LEFT JOIN controlling_line cl ON cl.order_id = co.order_id
)
SELECT order_id, month, category, line_revenue, line_units FROM attributed ORDER BY order_id;
EOF

